import{_ as s,o as a,c as o,af as e}from"./chunks/framework.B28LkSoM.js";const g=JSON.parse('{"title":"网络机器人概述","description":"爬虫的定义与应用场景、工作流程五步、数据清洗，以及 robots 协议（君子协定）的规则字段","frontmatter":{"title":"网络机器人概述","published":"2026-09-19T00:00:00.000Z","description":"爬虫的定义与应用场景、工作流程五步、数据清洗，以及 robots 协议（君子协定）的规则字段","tags":["Python","爬虫"],"image":"https://img.tsh520.cn/file/blog/post-covers/python-42-crawler.webp","order":42,"date":"2026-09-19T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Python学习笔记/42-网络机器人概述.md","filePath":"posts/学习文档/Python学习笔记/42-网络机器人概述.md"}'),n={name:"posts/学习文档/Python学习笔记/42-网络机器人概述.md"};function r(l,t,d,i,p,c){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789776000000"},[...t[0]||(t[0]=[e(`<h2 id="什么是网络机器人" tabindex="-1">什么是网络机器人 <a class="header-anchor" href="#什么是网络机器人" aria-label="Permalink to &quot;什么是网络机器人&quot;">​</a></h2><p>爬虫：也称为网络爬虫（网络机器人），是一种按照一定的预设规则，<strong>自动浏览并抓取网络数据</strong>的程序或脚本。</p><p>常见的应用场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>例子</th></tr></thead><tbody><tr><td>搜索引擎</td><td>百度、Google 的网页收录</td></tr><tr><td>舆情监控</td><td>抓取社交平台上的公开讨论做分析</td></tr><tr><td>商业分析</td><td>电商比价系统</td></tr><tr><td>AI 大模型训练语料</td><td>大规模采集公开文本</td></tr></tbody></table><h2 id="爬虫的工作流程-五步" tabindex="-1">爬虫的工作流程（五步） <a class="header-anchor" href="#爬虫的工作流程-五步" aria-label="Permalink to &quot;爬虫的工作流程（五步）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开始 → 发送HTTP请求 → 解析结果提取数据 → 数据处理(清洗) → 数据存储 → 结束</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p><strong>数据清洗</strong>：对采集到的原始数据进行处理、修正、转换和标准化的过程，目的是让数据变得<strong>规范、准确</strong>。比如把 <code>2h 20m</code> 统一换算成 <code>140</code> 分钟。</p></div><h2 id="robots-协议-君子协定" tabindex="-1">robots 协议（君子协定） <a class="header-anchor" href="#robots-协议-君子协定" aria-label="Permalink to &quot;robots 协议（君子协定）&quot;">​</a></h2><p>robots 协议也称为爬虫协议、爬虫规则，是指网站<strong>根目录下</strong>存放的一份文本文件 <code>robots.txt</code>，用于告诉爬虫哪些页面可以抓取、哪些不能抓取。</p><p>它叫&quot;君子协定&quot;是因为<strong>没有强制力</strong>——全凭爬虫自觉遵守。但请务必遵守：网站把它放在那里，就是明确表达了&quot;哪些内容欢迎你来抓&quot;。</p><p>一份 <code>robots.txt</code> 长这样（节选自真实网站）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-agent: *                          # 通用规则（针对所有爬虫）</span></span>
<span class="line"><span>Disallow: /wp-admin/</span></span>
<span class="line"><span>Allow: /wp-admin/admin-ajax.php</span></span>
<span class="line"><span>Sitemap: https://www.tiobe.com/sitemap_index.xml</span></span>
<span class="line"><span>Crawl-delay: 5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>User-agent: Wandoujia Spider           # 特定规则（只针对豌豆荚爬虫）</span></span>
<span class="line"><span>Disallow: /</span></span>
<span class="line"><span></span></span>
<span class="line"><span>User-agent: Mediapartners-Google       # 特定规则（只针对谷歌广告爬虫）</span></span>
<span class="line"><span>Disallow: /subject_search</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>User-agent</code></td><td>用户代理，通过这个标识确认爬虫的身份</td></tr><tr><td><code>Disallow</code></td><td>不允许访问的资源</td></tr><tr><td><code>Allow</code></td><td>允许访问的资源</td></tr><tr><td><code>Sitemap</code></td><td>网站地图，帮助爬虫更高效地获取网站内容</td></tr><tr><td><code>Crawl-delay</code></td><td>爬取间隔时间（秒），避免频繁访问把网站压垮</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/python学习笔记/43-requests发送网络请求/">requests 发送网络请求</a></li><li><a href="/posts/编程学习/python学习笔记/44-网页结构-html与css和js/">网页结构-HTML与CSS和JS</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>爬虫是一种按照一定的预设规则，自动浏览并<strong>抓取</strong>网络数据的程序或脚本</li><li>爬虫的五个应用场景：搜索引擎、<strong>舆情监控</strong>、商业分析、<strong>AI 大模型训练语料</strong>、……</li><li>工作流程五步：发送 HTTP 请求 → <strong>解析结果提取数据</strong> → 数据处理(清洗) → <strong>数据存储</strong></li><li>数据清洗的目的是让数据变得<strong>规范、准确</strong></li><li>robots 协议的文件叫 <code>robots.txt</code>，放在网站的<strong>根</strong>目录下</li><li>robots.txt 五个字段：<code>User-agent</code>、<code>Disallow</code>、<code>Allow</code>、<code>Sitemap</code>、<code>Crawl-delay</code></li><li><code>Crawl-delay: 5</code> 的含义是<strong>爬取间隔 5 秒</strong>（避免频繁访问给网站造成压力）</li><li>robots 协议被称为&quot;<strong>君子</strong>协议&quot;，因为它没有强制力</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><p>口头答得出来即可。</p><ul><li><p>[ ] <strong>2-1</strong> 爬虫的工作流程五步，按顺序说出来；并解释&quot;数据清洗&quot;为什么要放在&quot;解析&quot;之后</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按&quot;发出请求 → 拿到数据 → 清洗处理 → 存储&quot;这条链路回想五步；清洗动的是数据本身，所以必须先有提取出来的原始数据</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> 发送 HTTP 请求 → 解析结果提取数据 → 数据处理(清洗) → 数据存储。清洗放在解析之后，因为只有先从网页里把原始数据提取出来，才谈得上修正和标准化。</p></details></li><li><p>[ ] <strong>2-2</strong> robots.txt 里 <code>User-agent: * </code> 和 <code>User-agent: Mediapartners-Google</code> 的区别是什么？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：看这一栏写的是通配符还是一个具体的爬虫名字，再想这条规则会落到谁头上</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> <code>*</code> 是通用规则，对<strong>所有</strong>爬虫生效；指定名字的规则只对<strong>那个</strong>爬虫生效（比如谷歌广告爬虫）。当规则冲突时，更具体的规则优先。</p></details></li><li><p>[ ] <strong>2-3</strong> 如果你写的爬虫每秒请求目标网站 100 次，违反了 robots.txt 的哪个字段？可能造成什么后果？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：五个字段里哪一个管&quot;访问间隔/频率&quot;？再站到对方服务器的角度想：短时间被大量请求会怎样</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 违反 <code>Crawl-delay</code>（访问间隔）。后果：给对方服务器造成很大压力，轻则被封 IP / 封 User-Agent，重则影响网站正常用户访问。</p></details></li></ul>`,21)])])}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
